HERE=Path(__file__).resolve().parent
slides=[]
def add(ch,title,body,notes,source,kind=''):
 slides.append(dict(chapter=ch,title=title,body=body,notes=notes,source=source,kind=kind))
def table(headers,rows):
 return '<table><thead><tr>'+''.join('<th>'+x+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table>'
def cols(a,b):return '<div class="columns"><div>'+a+'</div><div>'+b+'</div></div>'
def call(t):return '<p class="takeaway">'+t+'</p>'
add('TESIS MDS · AVANCES AL 6 NOV 2026','Temporalidad y<br>señales multimodales', '<p class="lead">Predicción de atención y activación<br>durante la navegación web</p><div class="cover-meta">Mario · Avances de investigación<br>Problema, experimentos, auditorías y próximos pasos</div>', 'Versión inicial para discutir con el profesor. El recorrido diferencia hechos verificados, resultados históricos y decisiones aún abiertas. Los resultados de activación anteriores a GSR V2 no se usan para sostener la hipótesis.', 'documentacion/Cierre_Experimental_V2_01-11-2026.md','cover')
add('01 · PUNTO DE PARTIDA','El problema de investigación',cols('<p class="lead">La atención y la activación<br>cambian durante una sesión.</p><p>Un resumen estático puede ocultar transiciones y dependencias entre momentos.</p>','<h3>Pregunta</h3><p class="question">¿Incorporar historial mejora la predicción frente a un modelo que usa solo la ventana actual?</p>')+call('La comparación debe aislar el aporte del historial.'),'La tesis parte de la temporalidad y la fusión multimodal. El contraste más reciente usa estadísticas del historial; no demuestra por sí solo que el orden de la secuencia aporte información.', '../../documentos/01 Tesis MDS/Marco Teorico/Problema e hipótesis.md')
add('01 · PUNTO DE PARTIDA','Una hipótesis, dos resultados','<blockquote>Los modelos temporales multimodales obtienen un mejor desempeño fuera de muestra que los estáticos comparables.</blockquote>'+table(['Resultado','Definición operacional'],[['Atención','Pseudoetiqueta a partir de mirada y pupila'],['Activación','Pseudoetiqueta a partir de GSR']])+call('La hipótesis conjunta requiere evidencia en ambas tareas.'),'La formulación del manuscrito habla de emociones y atención. Aquí se presenta activación como alcance operacional de la señal GSR, sin inferir valencia ni emociones discretas. Debe quedar explícito en la redacción final.', '../../documentos/01 Tesis MDS/Marco Teorico/Problema e hipótesis.md')
add('02 · DATOS Y DISEÑO','Cuatro modalidades, sin etiqueta directa',table(['Modalidad','Información utilizada'],[['EEG','Actividad eléctrica y características espectrales'],['GSR','Componentes tónicos, fásicos y respuestas SCR'],['Eye tracking','Fijaciones, dispersión y trayectoria de mirada'],['Pupilometría','Cambios en el diámetro pupilar']])+call('Las etiquetas son aproximaciones derivadas de señales; no autorreportes ni medidas psicológicas independientes.'),'La Toma de Muestra 2 corresponde a registros de navegación web de 2025. No hay expresión facial en este conjunto. El alcance de cada señal debe distinguirse del constructo psicológico que se pretende aproximar.', '../../documentos/01 Tesis MDS/Marco Teorico/Problema e hipótesis.md')
add('02 · DATOS Y DISEÑO','Separar la etiqueta de sus predictores',table(['Tarea','Profesor: construye la etiqueta','Estudiante: intenta predecirla'],[['Atención','Mirada + pupila','EEG + GSR'],['Activación','GSR','EEG + mirada + pupila']])+call('Las señales docentes no entran directamente como predictores de su propia etiqueta.'),'El profesor es una regla de construcción de pseudoetiquetas, no una verdad externa. La separación reduce circularidad directa. Normalización y umbrales personales del profesor siguen siendo offline.', 'resultados/profesor_binario_reconstruido_29-10-2026/INFORME.md; resultados/etiquetas_gsr_calidad_v2_01-11-2026/INFORME.md')
add('02 · DATOS Y DISEÑO','Evaluación por participante','<div class="numbers"><div><strong>25</strong><span>entrenamiento</span></div><div><strong>8</strong><span>validación</span></div><div><strong>8</strong><span>test</span></div></div><p class="lead">Ventanas de 2 segundos, desplazadas 1 segundo.</p>'+call('Una persona pertenece a una sola partición. Las ventanas solapadas no son observaciones independientes.'),'41 participantes en las particiones principales. P29 se mantiene fuera del análisis principal por sensibilidad de sincronización. Los recuentos de ventanas cambian según la tarea y la versión de etiquetas. Validación y test tienen exposición histórica.', 'resultados/modelado/particion_participantes.csv; documentacion/Modelos_Temporales_07-09-2026.md')
add('03 · RECORRIDO EXPERIMENTAL','Cómo evolucionó el trabajo','<div class="timeline"><div><b>Inicio</b><p>Sincronización, calidad y primeras pseudoetiquetas</p></div><div><b>Septiembre</b><p>Baselines, redes temporales y estrategias de fusión</p></div><div><b>Octubre</b><p>Atención binaria, reconstrucción docente y EEG por canal</p></div><div><b>Noviembre</b><p>GSR V2, recálculo, auditoría y protocolo de hipótesis</p></div></div>','La evolución no es una curva de mejora de una única métrica: cambiaron tareas, etiquetas y representaciones. Las fechas son de las etapas de análisis, no de la adquisición de señales.', 'documentacion/Modelos_Temporales_07-09-2026.md; documentacion/Fusiones_10-09-2026.md; ../../notas/bitacora.md')
add('03 · RECORRIDO EXPERIMENTAL','Los primeros experimentos',cols('<h3>Modelos</h3><p>Logística, bosques y controles estáticos.<br>TCN, LSTM y BiLSTM.<br>Clasificación y regresión.</p>','<h3>Comparaciones</h3><p>Ventana actual frente a historial.<br>Modalidades individuales y fusión.<br>Controles para separar arquitectura e historial.</p>')+call('Esta etapa construyó el pipeline y los controles; sus etiquetas históricas requieren cautela.'),'En septiembre se guardaron 104 redes en la primera comparación temporal. También se exploraron fusión temprana y tardía, selección de variables, ensambles y otras arquitecturas. No se trasladan métricas antiguas al objetivo binario V2. La auditoría posterior detectó un problema en el generador histórico.', 'documentacion/Modelos_Temporales_07-09-2026.md; documentacion/Fusiones_10-09-2026.md; resultados/etiquetas_gsr_calidad_v2_01-11-2026/INFORME.md')
add('04 · ATENCIÓN','Reconstrucción del profesor de atención',cols('<h3>Etiqueta relativa</h3><p>Score de mirada y pupila, convertido en dos clases respecto de la mediana personal.</p>','<h3>Control de entrenamiento</h3><p>Componentes recalculados desde las características. PCA ajustado dentro de cada fold.</p>')+call('Se compararon profesores igualitario y PCA. Una AUC mayor no valida por sí sola el constructo de atención.'),'Reconstrucción del 29 de octubre: 25 participantes y 13.498 ventanas válidas de train; 26 omitidas por componentes incompletos. Cada profesor produjo 75 modelos estudiantes. La etiqueta usa normalización personal offline y no equivale a una medición psicológica independiente.', 'resultados/profesor_binario_reconstruido_29-10-2026/INFORME.md')
add('04 · ATENCIÓN','Recuperar información del EEG','<div class="numbers"><div><strong>16</strong><span>canales conservados</span></div><div><strong>342</strong><span>nuevas entradas EEG</span></div></div><p class="lead">Potencias por banda, descriptores espectrales,<br>características temporales y relaciones entre canales.</p>'+call('Crudos recuperados desde Drive y verificados; extracción alineada con las ventanas originales.'),'La etapa previa agregaba EEG entre canales. Se recuperaron archivos crudos, verificando integridad, y se extrajeron características por canal. Se comprobaron muestras y selección temporal contra el procesamiento anterior. No se atribuye localización anatómica sin mapa de electrodos.', 'documentacion/Crudos_V2_y_EEG_Por_Canal_29-10-2026.md; resultados/temporalidad_eeg_v2_test_29-10-2026/auditoria_extraccion.json')
add('04 · ATENCIÓN','El modelo cercano a 0,67', '<div class="hero-metric">0,6744<span>AUC test · CatBoost estático · atención</span></div><p class="lead">AUC en validación: <b>0,6798</b></p>'+call('Es desempeño de atención. No es el resultado de activación GSR ni una prueba aislada del aporte temporal.'),'Este es el modelo encontrado que coincide con la referencia del usuario a 0,67; la identificación es provisional. La AUC evalúa discriminación y no es porcentaje de aciertos. El comparador estático emparejado con el HistBoost temporal tiene otra AUC.', 'resultados/temporalidad_eeg_v2_test_29-10-2026/INFORME.md; resultados/temporalidad_eeg_v2_validacion_29-10-2026/INFORME.md')
add('04 · ATENCIÓN','Comparación temporal emparejada',table(['Modelo · test','AUC'],[['HistBoost estático','0,6602'],['HistBoost + historial hasta 32','<b>0,6879</b>']])+'<div class="delta">+0,0277 <span>ΔAUC · IC95% [−0,0041; +0,0505]</span></div>'+call('Mejora en 7 de 8 personas; el intervalo del contraste incluye cero.'),'La comparación mantiene familia y parámetros emparejados. Es el contraste histórico principal del 29 de octubre y no debe confundirse con la comparación contra CatBoost 0,6744. IC bootstrap pareado descriptivo; test previamente consultado.', 'resultados/temporalidad_eeg_v2_test_29-10-2026/INFORME.md')
add('04 · ATENCIÓN','Otra representación, otro experimento',table(['Comparación común · atención · test','AUC'],[['Estático','0,6602'],['Historial hasta 32','0,6927']])+'<div class="delta">+0,0325 <span>ΔAUC · IC95% [+0,0059; +0,0591]</span></div>'+call('Resultado favorable exploratorio. La representación temporal cambió y el test ya había sido utilizado.'),'La comparación común del 30 de octubre usa media y desviación histórica de todas las variables. No es la misma representación de la diapositiva anterior. Debe conservarse este resultado favorable, pero no presentarlo como réplica confirmatoria independiente ni como justificación de elegir una representación después de ver test.', 'resultados/comparacion_comun_binaria_30-10-2026/INFORME.md')
add('05 · AUDITORÍA GSR','El diagnóstico cambió la prioridad',cols('<h3>Calidad</h3><p>P4 tenía GSR válido en apenas el 12,6% de sus ventanas, pero todas recibían etiqueta.</p>','<h3>Consistencia</h3><p>Empates y clases muy desbalanceadas en algunas personas. Historial completo poco frecuente.</p>')+call('Antes de seguir buscando modelos, había que revisar la construcción de las etiquetas.'),'P34 tenía aproximadamente 8,6% de positivos bajo la etiqueta binaria anterior. El diagnóstico de 60 ajustes internos y 15 modelos externos se reprodujo, pero reproducibilidad no equivale a validez del objetivo. Sus resultados se consideran históricos, no evidencia con GSR V2.', 'resultados/activacion_diagnostico_nested_30-10-2026/INFORME.md; ../../notas/bitacora.md')
add('05 · AUDITORÍA GSR','Un error de alineación confirmado','<p class="lead">Al agrupar por participante y reiniciar índices,<br>los componentes podían asignarse a otras ventanas.</p><div class="hero-metric small">25.498 / 25.992<span>posiciones de componentes desplazadas en el archivo completo</span></div>'+call('Se reprodujeron los scores archivados con ese error. Los AUC de activación anteriores deben sustituirse por los recalculados.'),'La operación groupby/apply seguida de reset_index descartaba los índices originales. Las cifras corresponden al archivo completo, incluidos participantes fuera del análisis principal; no son el número de etiquetas binarias que cambiaron. Los errores máximos de reproducción fueron 4,82e-7 y 2,92e-7, compatibles con precisión de exportación. El patrón también aparece en atención histórica; no se extrapola a profesores reconstruidos posteriores.', 'resultados/etiquetas_gsr_calidad_v2_01-11-2026/INFORME.md; resultados/etiquetas_gsr_calidad_v2_01-11-2026/auditoria_independiente_02-11-2026.json')
add('05 · AUDITORÍA GSR','Etiquetas GSR V2','<ol class="steps"><li><b>Calidad de señal</b><span>Cobertura ≥50%, cuatro componentes finitos y SCR no negativos.</span></li><li><b>Identidad conservada</b><span>Normalización personal con ventanas válidas, sin perder correspondencia.</span></li><li><b>Soporte temporal</b><span>Cinco ventanas consecutivas válidas; reinicio ante huecos o cambios de segmento.</span></li><li><b>Etiqueta binaria</b><span>Mediana personal; empates y scores sin variación quedan sin etiqueta.</span></li></ol>','Cinco ventanas de dos segundos, desplazadas un segundo, cubren seis segundos. Los componentes observados constantes aportan cero; ausencias no se rellenan con cero. La mediana y normalización son offline. Esta revisión opera sobre características derivadas, no incorpora un detector fisiológico nuevo sobre señal cruda.', 'resultados/etiquetas_gsr_calidad_v2_01-11-2026/INFORME.md')
add('05 · AUDITORÍA GSR','Qué datos quedan para aprender',table(['Partición','Ventanas originales','Etiquetas V2'],[['Entrenamiento','13.524','7.028'],['Validación','4.662','2.584'],['Test','4.025','2.184']])+'<p class="lead"><b>11.796 etiquetas</b> · 53,1% de las ventanas principales</p>'+call('La mayor reducción se debe al historial insuficiente, no a mala señal GSR.'),'Se preservan las 22.211 filas originales con motivo de exclusión. Sin etiqueta: 9.995 por historial insuficiente, 401 por cobertura/flag y 19 por empate. Las 41 personas conservan ambas clases. P4 conserva 26 ventanas etiquetables de 459. Los modelos comparados usan exactamente las mismas filas V2.', 'resultados/etiquetas_gsr_calidad_v2_01-11-2026/INFORME.md')
add('06 · RESULTADOS CORREGIDOS','Activación: mismo modelo, distinto historial',table(['Contexto máximo','Validación','Test'],[['Actual · estático','0,5182','0,5141'],['8 ventanas','0,5209','<b>0,5470</b>'],['32 ventanas · principal','0,5245','0,5363']])+call('AUC promedio por participante · HistGradientBoosting · EEG + mirada + pupila'),'Selección solo dentro de train: 30 ajustes internos, 15 modelos externos OOF y tres modelos finales. 15 hojas compartidas entre contextos. Se reentrenó el 2 de noviembre con resultados idénticos a la ejecución V2 previa. Test: 8 participantes y 2.184 ventanas. Contexto 8 es secundario, no nuevo ganador seleccionado por test.', 'resultados/activacion_gsr_v2_recalculo_02-11-2026/INFORME.md')
add('06 · RESULTADOS CORREGIDOS','La diferencia importa tanto como la AUC',table(['Temporal − estático · test','ΔAUC','IC descriptivo 95%'],[['Hasta 8 · secundario','+0,0329','[+0,0076; +0,0592]'],['Hasta 32 · principal','+0,0222','[−0,0130; +0,0585]']])+call('La señal favorable de 8 ventanas en test no se confirma en validación ni en OOF train.'),'El contraste de 8 mejora en 7/8 personas, pero en validación Δ=+0,00269 con IC [-0,0260;0,0333] y OOF Δ=-0,00194 con IC [-0,0495;0,0491]. No inferir diferencias comparando solapamiento de intervalos de AUC individuales: aquí se usan diferencias pareadas. Los intervalos son exploratorios, sin corrección por búsqueda histórica.', 'resultados/activacion_gsr_v2_recalculo_02-11-2026/contrastes.csv')
add('06 · RESULTADOS CORREGIDOS','¿La fusión supera a cada modalidad?',table(['Activación · AUC test','Actual','Hasta 8','Hasta 32'],[['EEG','0,4982','0,5123','0,5173'],['Mirada','0,5151','0,5129','0,5215'],['Pupila','0,5172','0,5461','0,5386'],['Fusión completa','0,5141','0,5470','0,5363']])+call('Los nueve intervalos de fusión menos modalidad individual en test incluyen cero.'),'Ablación V2 con 54 modelos nuevos, mismos hiperparámetros, participantes y filas. 63 recargas predictivas, 492 AUC y 27 contrastes auditados. Estas ablaciones comparan fusión temprana con modalidades individuales; no completan el contraste entre fusión temprana, intermedia y tardía bajo etiquetas corregidas.', 'resultados/ablacion_modalidades_v2_01-11-2026/INFORME.md')
add('06 · RESULTADOS CORREGIDOS','32 es un máximo, no el historial real','<div class="numbers"><div><strong>8,73</strong><span>ventanas de historial medio<br>en test · contexto máximo 32</span></div><div><strong>0%</strong><span>de ventanas de test con<br>los 32 pasos completos</span></div></div>'+call('La evaluación mide estadísticas del historial disponible. No prueba secuencias completas de 32 ni sensibilidad al orden.'),'Promedio ponderado por ventanas en test. Hasta 8 tiene historia media 5,06 y 40,8% de historias completas. Hasta 32 reinicia ante huecos, segmento o estímulo. En V2 solo se utilizan filas etiquetadas para la representación histórica, por lo que se omiten ventanas iniciales válidas sin etiqueta.', 'resultados/activacion_gsr_v2_recalculo_02-11-2026/INFORME.md')
add('07 · ESTADO DE LA HIPÓTESIS','Qué podemos sostener hoy',cols('<h3>Evidencia disponible</h3><p>Atención: resultados favorables en algunos contrastes.<br><br>Activación: mejora secundaria en test, sin consistencia entre evaluaciones.</p>','<h3>Alcance</h3><p>La superioridad temporal conjunta sigue sin resolverse.<br><br>El test reutilizado no constituye una confirmación independiente.</p>')+call('Reproducir un resultado confirma su ejecución; no garantiza validez de la etiqueta ni generalización.'),'No se concluye que la temporalidad nunca sirve. Tampoco se declara validada la hipótesis general. Distinguir discriminación de pseudoetiquetas, mejora frente al estático y validez psicológica. La versión actual documenta estas tres dimensiones por separado.', 'documentacion/Cierre_Experimental_V2_01-11-2026.md; resultados/activacion_gsr_v2_recalculo_02-11-2026/INFORME.md')
add('07 · SIGUIENTE ETAPA','Una regla de decisión antes de evaluar','<p class="lead">Fijar qué mejora queremos demostrar<br>y contrastarla en participantes nuevos.</p>'+table(['Paso','Decisión pendiente'],[['Efecto relevante','Justificar el margen; +0,02 AUC es solo un escenario'],['Comparación','Modelos, etiquetas y contexto principal fijados'],['Evaluación','Mismas personas y ventanas por tarea; incertidumbre pareada']])+call('Con un margen positivo se prueba una mejora relevante, no la mera existencia de cualquier mejora.'),'El protocolo propuesto usa intervalos simultáneos en ambas tareas. Respaldo si ambos límites inferiores superan el margen; refutación de esa afirmación acotada si algún límite superior queda debajo; si cruzan el margen, el resultado sigue inconcluso. Un diseño honesto no garantiza una decisión binaria.', 'resultados/protocolo_hipotesis_reintento_06-11-2026/INFORME.md')
add('07 · CIERRE','Avances y decisiones para discutir','<ol class="steps"><li><b>Pipeline reconstruido y auditable</b><span>Datos, etiquetas, modelos y predicciones con trazabilidad.</span></li><li><b>Resultados corregidos y comparables</b><span>GSR V2, evaluación temporal y ablaciones sobre las mismas ventanas.</span></li><li><b>Próxima decisión metodológica</b><span>Alcance de la hipótesis, relevancia del efecto y factibilidad de evaluación independiente.</span></li></ol>','Cierre de la exposición principal. El aporte actual incluye auditoría y corrección del objetivo, controles comparables y una interpretación delimitada. Los anexos profundizan en métrica, muestras y fuentes. No se ha recolectado una cohorte nueva ni ejecutado el protocolo prospectivo.', 'resultados/protocolo_hipotesis_reintento_06-11-2026/INFORME.md','closing')
add('ANEXO A · MÉTRICA','Cómo leer la AUC',cols('<div class="hero-metric small">0,50<span>referencia de discriminación aleatoria</span></div>','<div class="hero-metric small">1,00<span>ordenamiento perfecto de las dos clases</span></div>')+'<p class="lead">AUC ≠ porcentaje de aciertos</p>'+call('Promediamos AUC por persona y comparamos diferencias dentro de cada persona.'),'Una AUC cercana a 0,67 no significa 67% de etiquetas correctas a un umbral dado. La discriminación se refiere a las pseudoetiquetas definidas. Para la hipótesis importa ΔAUC temporal menos estático y su incertidumbre, no superar un valor aislado.', 'resultados/temporalidad_eeg_v2_test_29-10-2026/INFORME.md')
add('ANEXO B · PLANIFICACIÓN','El tamaño de muestra aún no está fijado',table(['Escenario piloto','Personas nuevas evaluables'],[['Atención · dispersión del test histórico','62'],['Activación · dispersión de validación','72'],['Activación · dispersión de test','101'],['Activación · dispersión de OOF train','767']])+call('Escenario: margen 0,02 y efecto verdadero 0,04 o 0,00. Estas cifras no son una recomendación definitiva de reclutamiento.'),'Potencia 90% por tarea, intervalos bilaterales de 97,5% para control simultáneo. Se verificó el cálculo con 100.000 simulaciones por escenario bajo normalidad. Las varianzas externas usan ocho personas y OOF mezcla modelos de folds distintos; 767 es sensibilidad conservadora, no requerimiento demostrado. El estudio conjunto no suma los N si las personas son las mismas. El margen carece aún de justificación sustantiva independiente.', 'resultados/protocolo_hipotesis_reintento_06-11-2026/INFORME.md; resultados/protocolo_hipotesis_reintento_06-11-2026/verificacion_simulada.json')
add('ANEXO C · TRAZABILIDAD','Documentación que sostiene el relato','<ol class="sources"><li>Problema e hipótesis · manuscrito de investigación</li><li>Primeras redes y fusión · septiembre de 2026</li><li>Profesor reconstruido y EEG por canal · 29 de octubre</li><li>Temporalidad de atención y comparación común · 29–30 de octubre</li><li>GSR V2, auditoría y recálculo · 1–2 de noviembre</li><li>Ablaciones V2 y protocolo prospectivo · noviembre de 2026</li></ol>'+call('Las notas de cada diapositiva incluyen su fuente local y las precisiones metodológicas.'),'Todas las cifras proceden de los informes y tablas locales. Las comparaciones con etiquetas anteriores se presentan como historia de desarrollo. Consultar FUENTES.md para rutas completas y GUIÓN.md para el contenido y notas de toda la presentación.', 'FUENTES.md')
