slides=story(slides)
css='''
:root{--paper:#f6f4ef;--ink:#182e2a;--muted:#66716b;--line:#d7dcd4;--accent:#b9d3a7}*{box-sizing:border-box}body{margin:0;background:#e4e7df;color:var(--ink);font-family:Arial,Helvetica,sans-serif}button,a{touch-action:manipulation}button{font:inherit;cursor:pointer}button:focus-visible,a:focus-visible{outline:3px solid #71914a;outline-offset:4px}#stage{height:calc(100dvh - 62px);display:flex;align-items:center;justify-content:center;overflow:hidden}.slide{width:1280px;height:720px;padding:64px 82px 48px;background:var(--paper);position:relative;transform-origin:center;flex-shrink:0;display:none}.slide.active{display:block}.chapter{font-size:15px;letter-spacing:2px;font-weight:700;color:var(--muted);margin-bottom:28px}h1{font-size:49px;line-height:1.08;letter-spacing:-2px;font-weight:500;margin:0 0 30px;max-width:1090px}h3{font-size:20px;font-weight:600;margin:0 0 22px}p{font-size:24px;line-height:1.48;margin:0 0 20px}.lead{font-size:31px;line-height:1.35;letter-spacing:-.6px}.columns{display:grid;grid-template-columns:1fr 1fr;gap:68px}.question{font-size:31px;line-height:1.35}.takeaway{font-size:21px;line-height:1.35;border-top:1px solid var(--line);padding-top:20px;margin-top:28px;max-width:1080px;color:#41584d}blockquote{margin:8px 0 35px;font-size:35px;line-height:1.3;letter-spacing:-.7px;max-width:1050px}table{border-collapse:collapse;width:100%;font-size:23px;line-height:1.3}th{font-size:15px;text-transform:uppercase;letter-spacing:1px;text-align:left;color:var(--muted);font-weight:500;padding:0 18px 15px 0;border-bottom:1px solid var(--ink)}td{padding:20px 24px 20px 0;border-bottom:1px solid var(--line)}td:first-child{width:40%}td b{font-weight:700}table+.lead{margin-top:25px}.numbers{display:flex;gap:85px;margin:25px 0 45px}.numbers strong{display:block;font-size:106px;line-height:1;font-weight:400;letter-spacing:-6px}.numbers span{display:block;font-size:20px;line-height:1.4;margin-top:18px;color:var(--muted)}.hero-metric{font-size:116px;letter-spacing:-6px;line-height:1;font-weight:400;margin:15px 0 40px}.hero-metric span{display:block;font-size:21px;letter-spacing:0;line-height:1.4;margin-top:18px;color:var(--muted)}.hero-metric.small{font-size:76px;letter-spacing:-3px}.delta{font-size:61px;letter-spacing:-2px;margin-top:30px}.delta span{font-size:23px;letter-spacing:0;margin-left:20px}.timeline{display:grid;grid-template-columns:repeat(4,1fr);margin-top:70px;gap:26px}.timeline div{border-top:2px solid var(--ink);padding-top:22px}.timeline b{font-size:23px}.timeline p{font-size:22px;margin-top:22px}.steps{padding:0;list-style:none;counter-reset:item;margin:0}.steps li{position:relative;padding:16px 0 21px 65px;border-bottom:1px solid var(--line);counter-increment:item}.steps li:before{content:'0'counter(item);position:absolute;left:0;top:18px;font-size:21px;color:var(--muted)}.steps b{display:block;font-size:27px;font-weight:500;margin-bottom:9px}.steps span{font-size:21px;line-height:1.4;color:#536158}.sources{font-size:25px;line-height:1.5;padding-left:30px}.sources li{margin:15px 0}.cover{background:#183a31;color:var(--paper)}.cover .chapter{color:#c2d5bc}.cover h1{font-size:76px;max-width:1000px;letter-spacing:-3px;margin-top:65px}.cover .lead{font-size:29px;color:#d5dfd0}.cover-meta{font-size:18px;line-height:1.5;margin-top:55px;color:#c2d5bc}.closing{background:#e5ecdf}.folio{position:absolute;bottom:25px;right:38px;font-size:14px;color:var(--muted)}.cover .folio{color:#c2d5bc}.slide aside{display:none}nav{height:62px;padding:0 25px;display:flex;align-items:center;gap:12px;background:var(--paper);border-top:1px solid var(--line)}nav button{border:0;background:transparent;color:var(--ink);padding:10px 12px;border-radius:4px;font-size:14px}nav button:hover{background:#e4eadf}#counter{font-size:14px;font-variant-numeric:tabular-nums;min-width:60px;text-align:center}.spacer{flex:1}#progress{height:3px;background:var(--ink);position:fixed;bottom:0;left:0;transition:width .2s}.dialog{position:fixed;inset:8vh 8vw;background:var(--paper);z-index:5;padding:30px 42px;overflow:auto;border:1px solid var(--line);box-shadow:0 25px 100px #183a3140}.dialog[hidden]{display:none}.dialog h2{font-size:28px;font-weight:500}.dialog p{font-size:18px}.dialog a{color:var(--ink);overflow-wrap:anywhere}.close{float:right;border:0;background:none;font-size:22px;padding:8px}.index-list{display:grid;grid-template-columns:1fr 1fr;gap:4px 35px}.index-list button{text-align:left;font-size:17px;background:none;border:0;border-bottom:1px solid var(--line);padding:14px 0;line-height:1.3}.index-list span{color:var(--muted);padding-right:12px}.reading #stage{display:block;height:auto;overflow:visible}.reading .slide{display:block;transform:none!important;width:min(100%,1280px);height:auto;min-height:720px;margin:24px auto}.reading nav{position:sticky;bottom:0}.reading #progress{display:none}@media(max-width:650px){nav{padding:0 5px;gap:0}nav button{padding:10px 8px;font-size:12px}.hide-mobile{display:none}.dialog{inset:3vh 3vw;padding:20px}.index-list{grid-template-columns:1fr}.reading .slide{padding:40px 24px;min-height:0;margin:12px auto}.reading h1{font-size:32px;letter-spacing:-1px}.reading p,.reading .lead{font-size:20px}.reading .columns,.reading .timeline{grid-template-columns:1fr;gap:20px}.reading .numbers{gap:25px;flex-wrap:wrap}.reading .numbers strong{font-size:60px;letter-spacing:-3px}.reading .hero-metric{font-size:65px;letter-spacing:-3px}.reading .hero-metric.small{font-size:48px}.reading table{font-size:15px}.reading th{font-size:10px}.reading td{padding:14px 10px 14px 0}.reading .delta{font-size:40px}.reading .delta span{display:block;margin:12px 0;font-size:18px}.reading blockquote{font-size:25px}.reading .steps b{font-size:23px}.reading .steps span{font-size:18px}.reading .chapter{font-size:11px}.reading .folio{display:none}.reading .cover h1{margin-top:20px;font-size:42px}.reading .sources{font-size:18px}.reading .takeaway{font-size:18px}.reading .timeline{margin-top:25px}}@media print{@page{size:landscape;margin:0}body{background:white}#stage,.reading #stage{display:block;height:auto;overflow:visible}.slide,.slide.active,.reading .slide{display:block!important;transform:none!important;width:297mm;height:167mm;min-height:0;margin:0;padding:14mm 19mm;page-break-after:always;break-after:page;zoom:.88;print-color-adjust:exact;-webkit-print-color-adjust:exact}nav,#progress,.dialog{display:none!important}}
'''
css+=CSS+STORY_CSS
js='''
const DATA=__DATA__;
const stage=document.querySelector('#stage');
DATA.forEach((s,i)=>{const el=document.createElement('section');el.className='slide '+s.kind;el.id='slide-'+(i+1);el.setAttribute('aria-label',`Diapositiva ${i+1}: ${s.title.replace(/<[^>]+>/g,' ')}`);el.innerHTML=`<div class="chapter">${s.chapter}</div><h1>${s.title}</h1><div class="content">${s.body}</div><div class="folio">${String(i+1).padStart(2,'0')} / ${DATA.length}</div>`;stage.appendChild(el)});
const slides=[...document.querySelectorAll('.slide')];let index=0,lastFocus=null;
const initial=parseInt(location.hash.slice(1));if(initial>=1&&initial<=DATA.length)index=initial-1;
function fit(){const scale=Math.min((innerWidth-24)/1280,(innerHeight-86)/720);slides.forEach(s=>s.style.transform=`scale(${Math.max(.1,scale)})`)}
function show(n){index=Math.max(0,Math.min(DATA.length-1,n));slides.forEach((s,i)=>{s.classList.toggle('active',i===index);s.setAttribute('aria-hidden',String(!document.body.classList.contains('reading')&&i!==index))});document.querySelector('#counter').textContent=`${index+1} / ${DATA.length}`;document.querySelector('#progress').style.width=((index+1)/DATA.length*100)+'%';document.querySelector('#prev').disabled=index===0;document.querySelector('#next').disabled=index===DATA.length-1;history.replaceState(null,'','#'+(index+1));if(document.body.classList.contains('reading'))slides[index].scrollIntoView({behavior:'smooth',block:'start'})}
function closeDialogs(){document.querySelectorAll('.dialog').forEach(d=>d.hidden=true);if(lastFocus)lastFocus.focus()}
function openDialog(id){closeDialogs();lastFocus=document.activeElement;const d=document.getElementById(id);d.hidden=false;d.querySelector('button').focus()}
function sourceLink(src){let target;if(src==='FUENTES.md')target=src;else if(src.startsWith('../../../'))target='../../'+src;else if(src.startsWith('../../notas'))target='../../'+src;else target='../../'+src;const a=document.createElement('a');a.href=target;a.textContent=src;a.target='_blank';a.rel='noopener';return a}
function notes(){document.querySelector('#note-title').textContent=`${index+1}. ${DATA[index].title.replace(/<br>/g,' ')}`;document.querySelector('#note-text').textContent=DATA[index].notes;const list=document.querySelector('#note-sources');list.replaceChildren();DATA[index].source.split('; ').forEach(src=>{let p=document.createElement('p');p.appendChild(sourceLink(src));list.appendChild(p)});openDialog('notes')}
DATA.forEach((s,i)=>{let b=document.createElement('button');b.innerHTML=`<span>${String(i+1).padStart(2,'0')}</span>${s.title.replace(/<br>/g,' ')}`;b.onclick=()=>{closeDialogs();show(i)};document.querySelector('.index-list').appendChild(b)});
document.querySelector('#prev').onclick=()=>show(index-1);document.querySelector('#next').onclick=()=>show(index+1);document.querySelector('#overview').onclick=()=>openDialog('overview-panel');document.querySelector('#notes-button').onclick=notes;document.querySelectorAll('.close').forEach(b=>b.onclick=closeDialogs);document.querySelector('#print').onclick=()=>window.print();document.querySelector('#full').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen();else document.documentElement.requestFullscreen?.().catch(()=>{})};document.querySelector('#read').onclick=()=>{const on=document.body.classList.toggle('reading');document.querySelector('#read').textContent=on?'Presentar':'Lectura';show(index);fit()};
addEventListener('keydown',e=>{const dialog=[...document.querySelectorAll('.dialog')].find(d=>!d.hidden);if(dialog){if(e.key==='Escape'){closeDialogs();e.preventDefault()}if(e.key==='Tab'){const focus=[...dialog.querySelectorAll('button,a')];const first=focus[0],last=focus.at(-1);if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault()}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault()}}return}if(e.altKey||e.ctrlKey||e.metaKey)return;if(e.target.closest('button,a')&&[' ','Enter'].includes(e.key))return;if(['ArrowRight','PageDown',' '].includes(e.key)){show(index+1);e.preventDefault()}if(['ArrowLeft','PageUp'].includes(e.key)){show(index-1);e.preventDefault()}if(e.key==='Home')show(0);if(e.key==='End')show(DATA.length-1);if(e.key.toLowerCase()==='n')notes();if(e.key.toLowerCase()==='i')openDialog('overview-panel')});
addEventListener('resize',fit);addEventListener('hashchange',()=>{const n=parseInt(location.hash.slice(1));if(n>=1&&n<=DATA.length)show(n-1)});if(innerWidth<650){document.body.classList.add('reading');document.querySelector('#read').textContent='Presentar'}fit();show(index);
'''.replace('__DATA__',json.dumps(slides,ensure_ascii=False))
html='''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tesis MDS · Avances de investigación</title><style>'''+css+'''</style></head><body><main id="stage" aria-label="Presentación de avances"></main><nav aria-label="Controles de presentación"><button id="prev" aria-label="Diapositiva anterior">←</button><span id="counter" aria-live="polite"></span><button id="next" aria-label="Diapositiva siguiente">→</button><button id="overview">Índice</button><button id="notes-button">Notas</button><div class="spacer"></div><button id="read">Lectura</button><button id="full" class="hide-mobile">Pantalla completa</button><button id="print" class="hide-mobile">Imprimir</button></nav><div id="progress"></div><section class="dialog" id="notes" role="dialog" aria-modal="true" aria-labelledby="note-title" hidden><button class="close" aria-label="Cerrar notas">×</button><h2 id="note-title"></h2><p id="note-text"></p><h3>Fuentes</h3><div id="note-sources"></div></section><section class="dialog" id="overview-panel" role="dialog" aria-modal="true" aria-labelledby="overview-title" hidden><button class="close" aria-label="Cerrar índice">×</button><h2 id="overview-title">Recorrido de la presentación</h2><div class="index-list"></div></section><script>'''+js+'''</script></body></html>'''
(HERE/'index.html').write_text(html)
(HERE/'GUIÓN.md').write_text('# Avances de tesis · guion editable\n\n'+ '\n\n'.join(f'## {i+1:02d}. {s["title"].replace("<br>"," ")}\n\n{s["notes"]}' for i,s in enumerate(slides)))
sources=sorted({x for s in slides for x in s['source'].split('; ') if x!='FUENTES.md'})
(HERE/'FUENTES.md').write_text('# Fuentes de la presentación\n\nRutas relativas al repositorio, salvo indicación explícita. Los resultados antiguos son antecedentes, no resultados V2.\n\n'+'\n'.join('- '+s for s in sources))
(HERE/'LEEME.md').write_text('# Presentación HTML · versión narrativa 5\n\nAbrir index.html en el navegador. No necesita conexión ni librerías externas.\n\n- Flechas o espacio: avanzar/retroceder.\n- I: índice; N: notas y fuentes; Escape: cerrar panel.\n- Lectura: todas las diapositivas; modo inicial en móvil.\n- Imprimir: exportar desde el navegador.\n\nEl relato y el diseño están en relato.py; los gráficos se generan desde CSV en estilo_tecnico.py. Ejecutar crear_presentacion.py con el Python del entorno .venv regenera el HTML, gráficos y guion. Las versiones anteriores se conservan en version_1 a version_4. Para iterar, indicar número de diapositiva y cambio deseado.\n\n29 diapositivas: 25 principales y 4 anexos. Corte de información: 6 de noviembre de 2026.\n')
print(len(slides),'diapositivas',HERE/'index.html')
